/**
 * Returns the URL of the app logo: the app's own logo.svg, otherwise the App icon of the navigation profile.
 * @returns {Promise.<string>}
 */
export async function JSA_GetAppLogoUrl() {
	// BEGIN USER CODE
	const absolute = src => new URL(src, document.baseURI).toString();
	// 1. The app's own logo: logo.svg at the web root, which the login page shows too. Atlas Core ships a default
	//    one (public/logo.svg) for the login page, so the file always exists; the app's theme/web/logo.svg, or a
	//    theme module's public/logo.svg, replaces it. The default starts with a "Default app logo" comment.
	let hasDefaultLogo = false;
	try {
		const response = await fetch(absolute("logo.svg"), { credentials: "same-origin" });
		if (response.ok) {
			const svg = await response.text();
			if (!svg.includes("<!-- Default app logo")) {
				return absolute("logo.svg");
			}
			hasDefaultLogo = true;
		}
	} catch (error) {
		// fall through
	}
	// 2. Otherwise the App icon of the navigation profile, which every profile has, via the web manifest the runtime
	//    generates
	try {
		// the runtime only serves the manifest with the cache-bust query of its <link>, so without one there is none
		const link = document.querySelector("link[rel='manifest']");
		const response = link ? await fetch(link.getAttribute("href"), { credentials: "same-origin" }) : null;
		if (response && response.ok) {
			const manifest = await response.json();
			const icons = Array.isArray(manifest && manifest.icons) ? manifest.icons : [];
			const bySize = icons
				.map(icon => ({ src: icon.src || "", size: parseInt(String(icon.sizes || "0").split("x")[0], 10) || 0 }))
				.filter(icon => icon.src)
				.sort((a, b) => a.size - b.size);
			const pick = bySize.find(icon => icon.size >= 96) || bySize[bySize.length - 1];
			if (pick) {
				return absolute(pick.src);
			}
		}
	} catch (error) {
		// fall through
	}
	// 3. Only when the manifest cannot be read: the default logo, or nothing, and the layout shows its fallback image
	return hasDefaultLogo ? absolute("logo.svg") : "";
	// END USER CODE
}
